import{_ as a,o as r,c as o,a6 as t}from"./chunks/framework.DNkVJs23.js";const u=JSON.parse('{"title":"O Sapphire Star Codex","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://eurekaffeine.github.io/sapphire-star-codex/pl/others/"}],["meta",{"property":"og:url","content":"https://eurekaffeine.github.io/sapphire-star-codex/pl/others/"}],["meta",{"property":"og:title","content":"O Sapphire Star Codex | Sapphire Star Codex"}],["meta",{"property":"og:description","content":"Dane Monster Hunter i wyszukiwanie zestawów do Wilds, Rise z Sunbreak oraz World z Iceborne."}]]},"headers":[],"relativePath":"pl/others/index.md","filePath":"pl/others/index.md"}'),i={name:"pl/others/index.md"};function n(p,e,s,d,l,c){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="o-sapphire-star-codex" tabindex="-1">O Sapphire Star Codex <a class="header-anchor" href="#o-sapphire-star-codex" aria-label="Permalink to &quot;O Sapphire Star Codex&quot;">​</a></h1><h2 id="projekt" tabindex="-1">Projekt <a class="header-anchor" href="#projekt" aria-label="Permalink to &quot;Projekt&quot;">​</a></h2><p>Sapphire Star Codex łączy dane Monster Hunter z wyszukiwaniem zestawów pancerza. Aplikację samodzielnie tworzy i utrzymuje autor <a href="https://eurekaffeine.github.io/pocket-gallery/" target="_blank" rel="noreferrer">Pocket Gallery</a>. Jest bezpłatna, bez reklam i płatnych funkcji.</p><p>Android jest dostępny w <a href="https://play.google.com/store/apps/details?id=com.eurekaffeine.mhd" target="_blank" rel="noreferrer">Google Play</a>, a HarmonyOS w <a href="https://appgallery.huawei.com/app/detail?id=com.eurekaffeine.monsterhunterdex&amp;channelId=SHARE&amp;source=appshare" target="_blank" rel="noreferrer">AppGallery</a>. Wersja iOS jest przygotowywana. Zobacz <a href="./../#download">pobieranie</a>; dostępność zależy od regionu i urządzenia.</p><h2 id="uwagi-i-wspołpraca" tabindex="-1">Uwagi i współpraca <a class="header-anchor" href="#uwagi-i-wspołpraca" aria-label="Permalink to &quot;Uwagi i współpraca&quot;">​</a></h2><p>Zgłaszając problem, podaj grę, wpis, język, kroki i źródło umożliwiające sprawdzenie informacji. Ukryj dane osobowe na zrzutach. Kontakt: <a href="mailto:eurekaffeine.work@gmail.com" target="_blank" rel="noreferrer">eurekaffeine.work@gmail.com</a>. Pomocne są też polecenia aplikacji, poprawki i <a href="./../support/">dobrowolne wsparcie</a>.</p><h2 id="zrodła-i-prawa" tabindex="-1">Źródła i prawa <a class="header-anchor" href="#zrodła-i-prawa" aria-label="Permalink to &quot;Źródła i prawa&quot;">​</a></h2><p>Dane pochodzą m.in. z <a href="https://docs.wilds.mhdb.io/" target="_blank" rel="noreferrer">MHDB Wilds</a>, <a href="https://mhw-db.com/" target="_blank" rel="noreferrer">MHW DB</a> i plików gier, z porównaniem do źródeł społeczności. Mogą zawierać błędy lub braki. Nazwy, grafiki i dane Monster Hunter należą do CAPCOM; żądania ich usunięcia będą respektowane. Licencja MIT kodu zaadaptowanego z Pocket Gallery nie obejmuje grafik ani danych gier.</p>',8)])])}const k=a(i,[["render",n]]);export{u as __pageData,k as default};
